import { Pipe, PipeTransform } from '@angular/core';

const NUMBER = String.raw`(\d+(?:[.,]\d+)?)`;
const GRAMS = new RegExp(String.raw`^${NUMBER}\s*(?:grams?|gr|g)$`, 'i');
const MILLILITERS = new RegExp(String.raw`^${NUMBER}\s*(?:milliliters?|ml)$`, 'i');
const PIECES = new RegExp(String.raw`^${NUMBER}\s*pieces?$`, 'i');

/**
 * Writes a recipe quantity compactly, e.g. `150 gram` as `150g` or `2 piece` as `2 pieces`.
 * @param quantity - Quantity as generated by Gemini.
 * @returns The formatted quantity; unknown formats stay unchanged.
 */
export function formatQuantity(quantity: string): string {
  const value = quantity.trim();
  const grams = GRAMS.exec(value);
  if (grams) return `${grams[1]}g`;
  const milliliters = MILLILITERS.exec(value);
  if (milliliters) return `${milliliters[1]}ml`;
  const pieces = PIECES.exec(value);
  if (pieces) return pieces[1] === '1' ? '1 piece' : `${pieces[1]} pieces`;
  return value;
}

/** Formats recipe quantities, see {@link formatQuantity}. */
@Pipe({ name: 'quantity' })
export class QuantityPipe implements PipeTransform {
  /**
   * Formats a quantity.
   * @param quantity - Raw quantity.
   * @returns The formatted quantity.
   */
  transform(quantity: string): string {
    return formatQuantity(quantity);
  }
}
